"""Contact sheet rows for substitute teachers."""

from typing import List, Sequence

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def check_email(student: Student) -> None:
    """Refuse to list a student nobody can write to."""
    if not student.email:
        name = student.display_name
        raise ProjectError(f"no email for {name}")


def format_contacts(students: Sequence[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    if not students:
        raise ProjectError("no students for contact sheet")
    ordered = sorted(students, key=lambda s: s.display_name)
    # every student needs an email before any row is built
    for student in ordered:
        check_email(student)
    return _align(ordered)


def _align(ordered: Sequence[Student]) -> List[str]:
    wide = max(len(s.display_name) for s in ordered)
    sec = max(len(s.section) for s in ordered)
    return [
        f"{s.display_name:<{wide}}  {s.section:<{sec}}  {s.email}"
        for s in ordered
    ]

